(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-112":{scenario:{company:"Bamboo Crest Furniture",supervisor:{name:"Nguyễn Văn Khải",role:{vi:"Trưởng nhóm Thuế",en:"Tax Lead"}},ref_code:"VAT-2609",title:{vi:"Đúng thuế suất. Đúng khấu trừ. Đúng hạn.",en:"Right rate. Right credit. Right on time."},brief:{vi:"Bạn soát tờ khai thuế GTGT mẫu 01/GTGT tháng 09/2026 (VAT-2609), kê khai theo phương pháp khấu trừ. Doanh thu nội địa chưa thuế 2,4 tỷ đồng (thuế suất mô phỏng 10%); doanh thu xuất khẩu 1,5 tỷ đồng có hợp đồng, tờ khai hải quan và thanh toán qua ngân hàng. Thuế GTGT đầu vào trên hóa đơn hợp lệ 186 triệu đồng, trong đó 6,5 triệu đồng thuộc một hóa đơn 71,5 triệu đồng trả bằng tiền mặt. Không có thuế kỳ trước chuyển sang. Sửa thuế suất doanh thu xuất khẩu và số thuế còn phải nộp.",en:"You are reviewing VAT return form 01/GTGT for September 2026 (VAT-2609) under the credit method. Domestic sales excluding VAT are VND 2.4 billion (training rate 10%); export sales of VND 1.5 billion have a contract, customs declaration and bank payment. Input VAT on valid invoices is VND 186 million, of which VND 6.5 million belongs to a VND 71.5 million invoice paid in cash. There is no credit carried forward. Correct the export sales rate and the VAT payable."},reference_title:{vi:"Bảng kê hóa đơn & hồ sơ xuất khẩu đã duyệt · VAT-2609",en:"Approved invoice listing & export file · VAT-2609"},fields:[{id:"EXP_RATE",label:{vi:"Thuế suất GTGT của doanh thu xuất khẩu",en:"VAT rate on export sales"},initial:"KCT",expected:"0%",choices:["KCT","0%","10%"],reference:"Hồ sơ xuất khẩu & chính sách thuế",hint:{vi:"Hàng xuất khẩu đủ hợp đồng, tờ khai hải quan và thanh toán qua ngân hàng vẫn là đối tượng chịu thuế; điểm khác nằm ở quyền khấu trừ đầu vào.",en:"Exports with a contract, customs declaration and bank payment remain taxable; the difference lies in the right to credit input VAT."}},{id:"VAT_PAYABLE",label:{vi:"Thuế GTGT còn phải nộp (VND)",en:"VAT payable (VND)"},initial:"54000000",expected:"60500000",reference:"Bảng kê hóa đơn mua vào, bán ra",ref_value:{vi:"Doanh thu nội địa 2.400.000.000 đồng x 10%; đầu vào 186.000.000 đồng, gồm 6.500.000 đồng trả tiền mặt",en:"Domestic sales VND 2,400,000,000 x 10%; input VAT VND 186,000,000, including VND 6,500,000 paid in cash"},hint:{vi:"Không phải mọi số thuế ghi trên hóa đơn đầu vào đều được khấu trừ; kiểm tra điều kiện thanh toán của từng hóa đơn.",en:"Not every input VAT amount on an invoice is creditable; check the payment condition of each invoice."}}],sop32:{vi:"Thuế còn phải nộp = thuế GTGT đầu ra - thuế GTGT đầu vào đủ điều kiện khấu trừ - thuế kỳ trước chuyển sang; hóa đơn mua vào từ 5 triệu đồng trở lên (ngưỡng mô phỏng) trả bằng tiền mặt thì không được khấu trừ.",en:"VAT payable = output VAT - creditable input VAT - credit carried forward; purchase invoices of VND 5 million or more (training threshold) paid in cash are not creditable."},context:{label:"TỜ KHAI NHÁP 01/GTGT / VAT-2609",metrics:[{label:{vi:"Doanh thu nội địa",en:"Domestic sales"},value:"2,400,000,000 VND"},{label:{vi:"Doanh thu xuất khẩu",en:"Export sales"},value:"1,500,000,000 VND"},{label:{vi:"Thuế đầu vào trên hóa đơn",en:"Input VAT on invoices"},value:"186,000,000 VND"}]},crisis:{vi:"Một công ty dịch vụ gọi chào bán hóa đơn đầu vào trị giá 300 triệu đồng, thuế GTGT 30 triệu đồng, “không cần giao hàng, chuyển khoản xong bên em trả lại tiền mặt”. Giám đốc bảo bạn nhận để giảm số thuế tháng này.",en:"A service company offers to sell input invoices worth VND 300 million with VND 30 million VAT, “no delivery needed, you transfer and we return the cash”. The director tells you to take them to cut this month's tax."},options:{safe:{vi:"Từ chối mua hóa đơn không có giao dịch thật, kê khai đúng số thuế phải nộp, báo kế toán trưởng và giám đốc bằng văn bản về rủi ro pháp lý; đề xuất kế hoạch dòng tiền nộp thuế hợp pháp.",en:"Refuse invoices with no real transaction, file the correct VAT payable, warn the chief accountant and director in writing of the legal risk and propose a lawful tax cash plan."},shortcut:{vi:"Nhận hóa đơn để giảm 30 triệu đồng thuế, lưu chứng từ chuyển khoản cho có vẻ hợp lệ.",en:"Take the invoices to cut VND 30 million of tax and keep the transfer slip so it looks valid."},wait:{vi:"Chưa nộp tờ khai, chờ giám đốc tự quyết định và chấp nhận nộp chậm.",en:"Hold the return, wait for the director to decide and accept late filing."}},questions:{vi:["Vì sao doanh thu xuất khẩu áp dụng thuế suất 0% chứ không phải KCT? Trình bày cách bạn tính lại số thuế còn phải nộp.","Hóa đơn 71,5 triệu đồng trả tiền mặt cần xử lý thế nào và doanh nghiệp nên sửa quy trình thanh toán ra sao?"],en:["Why do export sales take the 0% rate rather than KCT? Show how you recalculated the VAT payable.","How should the VND 71.5 million cash-paid invoice be treated, and how should the payment process be fixed?"]},hints:{vi:["Đối chiếu từng dòng doanh thu trên tờ khai nháp với hồ sơ xuất khẩu đã duyệt trước khi chọn thuế suất.","Lọc bảng kê đầu vào theo hình thức thanh toán và áp điều kiện khấu trừ ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị mua bán hóa đơn phải bị từ chối và báo cáo bằng văn bản."],en:["Match each sales line on the draft return with the approved export file before choosing the rate.","Filter the input listing by payment method and apply the credit condition in SOP 3.2.","Re-read SOP 4.2: any offer to buy or sell invoices must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên kế toán thuế lập, kê khai và quyết toán các loại thuế như GTGT, TNDN, TNCN và thuế nhà thầu; kiểm soát hóa đơn đầu vào, đầu ra; xác định chi phí được trừ; theo dõi nghĩa vụ nộp và làm việc với cơ quan thuế khi kiểm tra, thanh tra hoặc hoàn thuế. Giá trị tạo ra là tuân thủ đầy đủ, tránh truy thu và phạt, đồng thời tận dụng hợp pháp các ưu đãi. Nghề đòi hỏi cập nhật văn bản liên tục và giữ chuẩn mực liêm chính.",en:"A tax accountant prepares, files and finalizes taxes such as VAT, corporate income tax, personal income tax and foreign contractor tax; controls input and output invoices; determines deductible expenses; tracks payment obligations and works with the tax authority on audits, inspections and refunds. The value is full compliance, no back taxes or penalties and lawful use of incentives. The role requires constant regulatory updates and firm integrity."},responsibilities:{vi:["Lập và nộp tờ khai thuế GTGT, TNCN, thuế nhà thầu theo tháng hoặc quý đúng hạn.","Kiểm tra tính hợp pháp và trạng thái hóa đơn đầu vào trước khi khấu trừ.","Tạm tính, quyết toán thuế TNDN và xác định chi phí được trừ, không được trừ.","Chuẩn bị hồ sơ hoàn thuế GTGT cho hàng xuất khẩu và giải trình khi được yêu cầu.","Cập nhật văn bản pháp luật thuế và đề xuất quy trình kiểm soát rủi ro thuế."],en:["Prepare and file monthly or quarterly VAT, PIT and contractor tax returns on time.","Check legality and status of input invoices before claiming credits.","Make provisional and annual CIT filings and determine deductible and non-deductible costs.","Prepare VAT refund files for exports and provide explanations on request.","Track tax law updates and propose tax risk control procedures."]},competencies:[{name:{vi:"Kê khai thuế GTGT",en:"VAT compliance"},desc:{vi:"Phân biệt thuế suất, đối tượng không chịu thuế, điều kiện khấu trừ và hoàn thuế.",en:"Distinguish rates, exempt supplies, credit conditions and refund rules."}},{name:{vi:"Thuế TNDN & chi phí được trừ",en:"CIT & deductible costs"},desc:{vi:"Điều chỉnh từ lợi nhuận kế toán sang thu nhập tính thuế và lập tờ khai quyết toán.",en:"Adjust accounting profit to taxable income and prepare the annual return."}},{name:{vi:"Kiểm soát hóa đơn điện tử",en:"E-invoice control"},desc:{vi:"Tra cứu trạng thái hóa đơn, người bán và chứng từ thanh toán trước khi ghi nhận.",en:"Check invoice status, seller status and payment evidence before recording."}},{name:{vi:"Đọc hiểu văn bản pháp luật",en:"Regulatory interpretation"},desc:{vi:"Tìm đúng văn bản đang hiệu lực, hiểu điều khoản chuyển tiếp và áp dụng vào nghiệp vụ.",en:"Find the effective rule, understand transition clauses and apply them to transactions."}},{name:{vi:"Liêm chính & quản trị rủi ro thuế",en:"Integrity & tax risk"},desc:{vi:"Từ chối hóa đơn không có giao dịch thật, cảnh báo rủi ro và lưu hồ sơ đầy đủ.",en:"Refuse invoices without real transactions, flag risks and keep full records."}}],knowledge:{vi:["Luật Quản lý thuế số 38/2019/QH14, Nghị định 126/2020/NĐ-CP và Thông tư 80/2021/TT-BTC về khai, nộp thuế (cùng văn bản sửa đổi, thay thế).","Luật Thuế giá trị gia tăng số 48/2024/QH15 (hiệu lực từ 01/07/2025): đối tượng chịu thuế, thuế suất, khấu trừ, hoàn thuế.","Nghị định 123/2020/NĐ-CP và Thông tư 78/2021/TT-BTC về hóa đơn điện tử.","Luật Thuế TNDN và văn bản hướng dẫn hiện hành về doanh thu, chi phí được trừ và ưu đãi.","VAS 17 Thuế thu nhập doanh nghiệp và Nghị định 132/2020/NĐ-CP về giao dịch liên kết."],en:["Tax Administration Law No. 38/2019/QH14, Decree 126/2020/ND-CP and Circular 80/2021/TT-BTC on filing and payment (with amending or replacing documents).","VAT Law No. 48/2024/QH15 (effective 1 July 2025): taxable supplies, rates, credits and refunds.","Decree 123/2020/ND-CP and Circular 78/2021/TT-BTC on e-invoices.","The current CIT Law and guidance on revenue, deductible costs and incentives.","VAS 17 Income taxes and Decree 132/2020/ND-CP on related-party transactions."]},tools:["Cổng thuế điện tử","Phần mềm hỗ trợ kê khai thuế","Hệ thống hóa đơn điện tử","Phần mềm kế toán (ERP)","Microsoft Excel"],kpis:{vi:["Tỷ lệ tờ khai nộp đúng hạn và không phải khai bổ sung.","Số tiền truy thu, phạt sau kiểm tra thuế (mục tiêu bằng 0).","Tỷ lệ hóa đơn đầu vào được tra cứu trạng thái trước khi kê khai.","Thời gian hoàn tất hồ sơ hoàn thuế GTGT."],en:["Share of returns filed on time with no amendments.","Back taxes and penalties after audits (target zero).","Share of input invoices status-checked before filing.","Time to complete a VAT refund file."]},day:[{time:"08:00",vi:"Tải hóa đơn điện tử đầu vào mới, tra cứu trạng thái người bán và hóa đơn.",en:"Download new input e-invoices and check seller and invoice status."},{time:"10:00",vi:"Đối chiếu doanh thu trên hóa đơn với sổ kế toán và hồ sơ xuất khẩu.",en:"Match invoiced sales with the ledger and the export files."},{time:"13:30",vi:"Lập tờ khai thuế GTGT và bảng tính thuế nhà thầu cho hợp đồng dịch vụ nước ngoài.",en:"Prepare the VAT return and the contractor tax worksheet for a foreign service contract."},{time:"15:30",vi:"Rà soát chi phí không được trừ cho tạm tính thuế TNDN quý.",en:"Review non-deductible costs for the quarterly CIT provisional filing."},{time:"17:00",vi:"Nộp tờ khai, lưu biên nhận điện tử và cập nhật lịch nghĩa vụ thuế.",en:"File the return, save the e-receipt and update the tax calendar."}],mistakes:{vi:["Coi doanh thu xuất khẩu là không chịu thuế, mất quyền khấu trừ và hoàn thuế đầu vào.","Khấu trừ thuế của hóa đơn trả tiền mặt vượt ngưỡng hoặc của người bán đã ngừng hoạt động.","Đưa chi phí không có hóa đơn hợp lệ hoặc không phục vụ kinh doanh vào chi phí được trừ."],en:["Treating exports as exempt, losing the right to credit and refund input VAT.","Crediting VAT on cash-paid invoices above the threshold or from sellers that ceased operation.","Deducting costs without valid invoices or not related to the business."]},career:[{vi:"Nhân viên kế toán thuế",en:"Tax accounting assistant"},{vi:"Chuyên viên thuế doanh nghiệp",en:"Corporate tax specialist"},{vi:"Quản lý thuế",en:"Tax manager"},{vi:"Giám đốc thuế (Head of Tax)",en:"Head of Tax"}],glossary:[{term:"Khấu trừ thuế GTGT",vi:"Trừ thuế GTGT đầu vào đủ điều kiện khỏi thuế GTGT đầu ra để xác định số phải nộp.",en:"VAT credit: deducting eligible input VAT from output VAT to find the amount payable."},{term:"KCT",vi:"Hàng hóa, dịch vụ không chịu thuế GTGT; thuế đầu vào liên quan không được khấu trừ.",en:"VAT-exempt supplies; related input VAT cannot be credited."},{term:"Thuế suất 0%",vi:"Thuế suất áp dụng cho hàng xuất khẩu đủ điều kiện; đầu ra bằng 0 nhưng vẫn được khấu trừ đầu vào.",en:"The rate for qualifying exports; output VAT is zero but input VAT remains creditable."},{term:"Chi phí được trừ",vi:"Chi phí thực tế phát sinh, phục vụ kinh doanh, có hóa đơn, chứng từ hợp lệ khi tính thuế TNDN.",en:"Deductible expense: a real business cost with valid invoices and documents for CIT."},{term:"FCT",vi:"Thuế nhà thầu nước ngoài, áp dụng cho thu nhập của tổ chức, cá nhân nước ngoài từ Việt Nam.",en:"Foreign contractor tax on income that foreign entities or individuals earn from Vietnam."}],quiz:[{q:{vi:"Thuế đầu ra 150 triệu đồng; đầu vào trên hóa đơn 120 triệu đồng, trong đó 4 triệu đồng không đủ điều kiện khấu trừ; kỳ trước chuyển sang 10 triệu đồng. Thuế còn phải nộp?",en:"Output VAT is VND 150 million; input VAT on invoices is VND 120 million, of which VND 4 million is not creditable; credit carried forward is VND 10 million. What is payable?"},options:{vi:["20 triệu đồng","30 triệu đồng","24 triệu đồng","34 triệu đồng"],en:["VND 20 million","VND 30 million","VND 24 million","VND 34 million"]},answer:2,explain:{vi:"Đầu vào được khấu trừ 116 triệu đồng; 150 - 116 - 10 = 24 triệu đồng.",en:"Creditable input VAT is VND 116 million; 150 - 116 - 10 = VND 24 million."}},{q:{vi:"Điểm khác biệt quan trọng giữa hàng xuất khẩu thuế suất 0% và hàng không chịu thuế GTGT là gì?",en:"What is the key difference between 0% rated exports and VAT-exempt supplies?"},options:{vi:["Hàng 0% được khấu trừ, hoàn thuế đầu vào; hàng không chịu thuế thì không","Không có khác biệt vì đầu ra đều bằng 0","Hàng không chịu thuế được hoàn thuế nhanh hơn","Hàng 0% không phải lập hóa đơn"],en:["0% rated goods allow input credit and refunds; exempt goods do not","No difference since output VAT is zero in both","Exempt goods get faster refunds","0% rated goods need no invoice"]},answer:0,explain:{vi:"Cả hai đều có thuế đầu ra bằng 0, nhưng chỉ hàng chịu thuế suất 0% mới được khấu trừ, hoàn thuế đầu vào.",en:"Both have zero output VAT, but only 0% rated supplies keep the right to credit and refund input VAT."}},{q:{vi:"Khoản nào thường KHÔNG được tính vào chi phí được trừ khi xác định thu nhập chịu thuế TNDN?",en:"Which item is normally NOT deductible when computing CIT taxable income?"},options:{vi:["Tiền lương có hợp đồng và chứng từ chi trả","Tiền phạt vi phạm hành chính","Khấu hao TSCĐ dùng cho sản xuất","Chi phí thuê văn phòng có hóa đơn"],en:["Salaries with contracts and payment proof","Administrative fines","Depreciation of production assets","Office rent with an invoice"]},answer:1,explain:{vi:"Tiền phạt vi phạm hành chính là khoản không được trừ; các khoản còn lại được trừ khi đủ hồ sơ.",en:"Administrative fines are non-deductible; the other items are deductible when properly documented."}},{q:{vi:"Giám đốc yêu cầu mua hóa đơn đầu vào không có giao dịch thật để giảm thuế. Bạn làm gì?",en:"The director asks you to buy input invoices with no real transaction to cut tax. What do you do?"},options:{vi:["Mua vì giám đốc đã đồng ý","Mua một nửa để giảm rủi ro","Chờ cơ quan thuế kiểm tra rồi tính","Từ chối, kê khai đúng và báo cáo rủi ro bằng văn bản"],en:["Buy them since the director agreed","Buy half to reduce risk","Wait for a tax audit and see","Refuse, file correctly and report the risk in writing"]},answer:3,explain:{vi:"Mua bán hóa đơn không có giao dịch thật là hành vi vi phạm pháp luật nghiêm trọng; phải từ chối và lưu bằng chứng.",en:"Trading invoices without real transactions is a serious legal violation; refuse and keep evidence."}}],tools_en:["E-tax portal","Tax filing support software","E-invoicing system","Accounting software (ERP)","Microsoft Excel"]}}})})(window.KKR);
